"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["65570"],{14261(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>u,assets:()=>l});var o=JSON.parse('{"id":"tianya/gobacktoschool","title":"","description":"Probably a legacy of the May Fourth Movement and the Cultural Revolution, both online and in reality there are people who love cursing Confucianism, as if that\'s what it means to be modernized. But how many of those who curse Confucianism actually understand it? Do those people really think the \\"Three Obediences and Four Virtues\\" and \\"ruler be ruler, minister be minister\\" is all there is to Confucianism? That\'s absolutely shooting at the wrong target. Even if Confucianism deserves cursing, at least wait until you\'ve read and understood all the Confucian classics before cursing -- otherwise what right do you have?","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/gobacktoschool.md","sourceDirName":"tianya","slug":"/tianya/gobacktoschool","permalink":"/en/tianya/gobacktoschool","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"gobacktoschool","title":"","hide_table_of_contents":true,"sidebar_label":"Of those who curse Confucianism all day, how many truly understand it? Go back and study properly \u2014 stop embarrassing yourselves"},"sidebar":"tianyaSidebar","previous":{"title":"Regardless of what Lu Xun was, when invoking Lu Xun, one\'s stance need not align with his!","permalink":"/en/tianya/luxunposition"},"next":{"title":"If we Chinese don\'t deeply reflect on ourselves, Japanese admissions of guilt are useless!!!","permalink":"/en/tianya/nousejapanesepleadguilty"}}'),a=t(74848),i=t(28453);let s={id:"gobacktoschool",title:"",hide_table_of_contents:!0,sidebar_label:"Of those who curse Confucianism all day, how many truly understand it? Go back and study properly \u2014 stop embarrassing yourselves"},r="How Many of Those Who Curse Confucianism All Day Actually Understand It? Go Back and Study Properly -- Stop Making Fools of Yourselves!",l={},u=[];function h(e){let n={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"how-many-of-those-who-curse-confucianism-all-day-actually-understand-it-go-back-and-study-properly----stop-making-fools-of-yourselves",children:"How Many of Those Who Curse Confucianism All Day Actually Understand It? Go Back and Study Properly -- Stop Making Fools of Yourselves!"})}),"\n",(0,a.jsx)(n.p,{children:'Probably a legacy of the May Fourth Movement and the Cultural Revolution, both online and in reality there are people who love cursing Confucianism, as if that\'s what it means to be modernized. But how many of those who curse Confucianism actually understand it? Do those people really think the "Three Obediences and Four Virtues" and "ruler be ruler, minister be minister" is all there is to Confucianism? That\'s absolutely shooting at the wrong target. Even if Confucianism deserves cursing, at least wait until you\'ve read and understood all the Confucian classics before cursing -- otherwise what right do you have?'}),"\n",(0,a.jsx)(n.p,{children:"This bad habit first came from the so-called May Fourth elites. Which of them truly understood Confucianism? For example, Hu Shi's understanding of Confucianism was as absurdly laughable as his understanding of Chan Buddhism. As for others like Lu Xun, they weren't much better. What happened afterward, everyone knows -- Confucianism became the epitome of feudal reaction, and then there were even fewer people studying it."}),"\n",(0,a.jsx)(n.p,{children:"The Chinese are already famous for not cherishing their own culture. Who knows how many classics were ultimately recovered from Japan, Korea, and other places. Moreover, Chinese people oscillate between doubting antiquity and worshipping antiquity like a revolving wheel, just like leftists and rightists. But both swallow learning whole without chewing, and their arguments never hit the mark. Now look at those Cultural Revolution articles criticizing Confucius -- they're laughable to the extreme."}),"\n",(0,a.jsx)(n.p,{children:"Confucianism is one of the foundations of Chinese civilization. Without Confucianism, there would be no Chinese civilization. Confucianism of course has problems, but the problems of Confucianism aren't something ordinary people can explain by spouting a couple of careless sentences. From Confucius to Zisi, Mencius, Han Dynasty Confucianism, Song Dynasty Neo-Confucianism, and Ming Dynasty School of the Mind -- the logical developmental trajectory among them is neither blind nor something that can be negated at will."}),"\n",(0,a.jsx)(n.p,{children:"You want to curse Confucianism? Fine, but let me ask: do you know what Confucianism is?"})]})}function c(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},28453(e,n,t){t.d(n,{R:()=>s,x:()=>r});var o=t(96540);let a={},i=o.createContext(a);function s(e){let n=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);